  // Every step gets a Figure; rows of at most 4 keep them all visible without scrolling.
  const steps = [...chain.steps].sort((a, b) => a.no - b.no)
  const rows = Array.from({ length: Math.ceil(steps.length / 4) }, (_, i) =>
